const $=s=>document.querySelector(s);const htmlEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={tasks:[],meetings:[],employees:[],events:[],projects:[],messages:[],threads:{},jobs:[]};let session=null;let cs='';let selectedMeetingId=null;let page='office',filter='all',search='',modal=null,chatBusy=false,callState='idle',recognizer=null,spoken=false,chatEmployee='devy',callAwaiting=false,callOutputId='';
const nav=[['inbox','Home','⌂'],['office','Office','▦'],['work','Work','▤'],['people','People','◉'],['boss','Boss','◈'],['history','Activity','◷'],['settings','Settings','⚙']];
const fDate=s=>s?new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'No due date';const niceStatus=s=>({todo:'To do',doing:'In progress',review:'Review',done:'Completed'})[s]||s;
const toast=t=>{const old=$('.toast');old?.remove();const n=document.createElement('div');n.className='toast';n.textContent=t;document.body.append(n);setTimeout(()=>n.remove(),4500)};
async function api(path,method='GET',payload){const resp=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{...(payload?{'content-type':'application/json'}:{}),...(cs&&method!=='GET'?{'x-office-csrf':cs}:{})},body:payload?JSON.stringify(payload):undefined});let json={};try{json=await resp.json()}catch{}if(!resp.ok)throw Error(json.error||('Request failed '+resp.status));return json}
async function refresh(){const d=await api('state');data=d;render()}
function setPage(p){page=p;search='';render();if(p==='boss')setTimeout(()=>{$('.chatstream')?.scrollTo(0,999999)},0)}
function rootFrame(inner){const pending=data.tasks.filter(t=>t.status==='review').length;return '<div class="app"><aside class="sidebar"><div class="brand"><img src="/icon.png" alt="">Devydtz Office</div><nav class="nav">'+nav.map(n=>'<button class="'+(page===n[0]?'active':'')+'" data-nav="'+n[0]+'"><span style="font-size:17px;width:18px">'+n[2]+'</span>'+n[1]+(n[0]==='inbox'&&pending?'<span class="num">'+pending+'</span>':'')+'</button>').join('')+'</nav><div class="grow"></div><div class="foot"><span class="kpi-dot"></span>Private workspace</div></aside><div class="body"><header class="top"><span class="top-title">'+htmlEscape(nav.find(x=>x[0]===page)?.[1])+'</span><div class="top-actions"><input id="quicksearch" placeholder="Search work" aria-label="Search work" value="'+htmlEscape(search)+'"><button class="btn ghost" id="logout">Sign out</button></div></header><main class="main">'+inner+'</main></div><nav class="bottomnav">'+nav.slice(0,5).map(n=>'<button data-nav="'+n[0]+'" class="'+(page===n[0]?'active':'')+'"><span class="symbol">'+n[2]+'</span>'+n[1]+'</button>').join('')+'</nav></div>'+ (modal?modalHtml():'')}
function heading(title,subtitle,btn=''){return '<div class="pagehead"><div><h1>'+title+'</h1><p class="muted">'+subtitle+'</p></div>'+btn+'</div>'}
function taskRow(t){const person=data.employees.find(e=>e.id===t.employee);return '<div class="row"><div class="rowmain"><div class="rowtitle">'+htmlEscape(t.title)+'</div><div class="rowmeta">'+htmlEscape(person?.name||'Unassigned')+' · '+niceStatus(t.status)+' · '+fDate(t.created)+'</div></div>'+ (t.priority==='urgent'||t.priority==='high'?'<span class="pill '+t.priority+'">'+t.priority+'</span>':'')+'<button class="btn ghost" data-task="'+t.id+'">Open</button></div>'}
function inbox(){const reviews=data.tasks.filter(t=>t.status==='review');const recent=data.tasks.filter(t=>t.status!=='done').slice(0,8);return heading('Your work','Your priorities and the team’s progress.','<button class="btn primary" data-create>+ New task</button>')+'<div class="grid metrics section"><div class="panel metric"><span>Open tasks</span><strong>'+data.tasks.filter(t=>t.status!=='done').length+'</strong></div><div class="panel metric"><span>In progress</span><strong>'+data.tasks.filter(t=>t.status==='doing').length+'</strong></div><div class="panel metric"><span>Needs review</span><strong>'+reviews.length+'</strong></div></div><section class="section"><div class="sectionhead"><h2>Needs your attention</h2><button class="btn ghost" data-nav="work">View work</button></div><div class="panel">'+(reviews.length?reviews.map(taskRow).join(''):'<div class="empty"><strong>Nothing waiting for review</strong>Work that needs your decision will appear here.</div>')+'</div></section><section class="section"><div class="sectionhead"><h2>Current work</h2></div><div class="panel">'+(recent.length?recent.map(taskRow).join(''):'<div class="empty"><strong>No tasks yet</strong>Create your first task and assign a specialist.</div>')+'</div></section>'}
function work(){const relevant=data.tasks.filter(t=>(filter==='all'||t.status===filter)&&(!search||t.title.toLowerCase().includes(search.toLowerCase())));return heading('Work','Create, assign, and review tasks.','<button class="btn primary" data-create>+ New task</button>')+'<div class="tabs">'+[['all','All'],['todo','To do'],['doing','In progress'],['review','Review'],['done','Completed']].map(x=>'<button class="'+(filter===x[0]?'active':'')+'" data-filter="'+x[0]+'">'+x[1]+'</button>').join('')+'</div><div class="panel">'+(relevant.length?'<table class="tasks-table"><thead><tr><th>Task</th><th>Assigned to</th><th>Updated</th><th>Status</th></tr></thead><tbody>'+relevant.map(t=>'<tr data-task="'+t.id+'"><td><strong>'+htmlEscape(t.title)+'</strong>'+(t.priority!=='normal'?' <span class="pill '+t.priority+'">'+t.priority+'</span>':'')+'</td><td>'+htmlEscape(data.employees.find(e=>e.id===t.employee)?.name||'Unassigned')+'</td><td class="muted">'+fDate(t.updated)+'</td><td><span class="pill">'+niceStatus(t.status)+'</span></td></tr>').join('')+'</tbody></table>':'<div class="empty"><strong>No matching tasks</strong>Try another filter or create a task.</div>')+'</div>'}
function people(){return heading('People','Each employee has a defined specialty and assigned work.','')+'<div class="grid">'+data.employees.map(e=>{const open=data.tasks.filter(t=>t.employee===e.id&&t.status!=='done').length;return '<div class="panel person"><div class="person-top"><div class="avatar">'+e.symbol+'</div><div><div class="title">'+e.name+'</div><div class="role">'+e.role+'</div></div></div><div class="desc">'+e.focus+'</div><div class="count">'+open+' open task'+(open===1?'':'s')+'</div></div>'}).join('')+'</div><p class="meta-note" style="margin-top:17px">Employees are specializations and task owners. They do not run autonomous AI models until a model and execution tools are configured.</p>'}
function formatOfficeText(text){return window.OfficeMarkdown?OfficeMarkdown(text):legacyFormatOfficeText(text)}
function legacyFormatOfficeText(text){
 const input=String(text||'');const lines=input.split('\\n');let html='',inCode=false,code=[];
 const inline=(value)=>htmlEscape(value).replace(/\`([^\`]+)\`/g,'<code>$1</code>').replace(/\\*\\*([^*]+)\\*\\*/g,'<strong>$1</strong>');
 const flush=()=>{if(code.length){html+='<pre><code>'+htmlEscape(code.join('\\n'))+'</code></pre>';code=[]}};
 for(const line of lines){
  if(/^\\s*\`\`\`/.test(line)){if(inCode)flush();inCode=!inCode;continue}
  if(inCode){code.push(line);continue}
  if(/^\\s*#{1,3} /.test(line)){html+='<h3>'+inline(line.replace(/^\\s*#{1,3} /,''))+'</h3>';continue}
  if(/^\\s*[-*] /.test(line)){html+='<div class="answer-list">• '+inline(line.replace(/^\\s*[-*] /,''))+'</div>';continue}
  if(/^\\s*\\d+\\. /.test(line)){html+='<div class="answer-list">'+inline(line)+'</div>';continue}
  html+=line.trim()?'<p>'+inline(line)+'</p>':'<div class="answer-gap"></div>';
 }
 if(inCode)flush();return html||'<p class="muted">No response yet.</p>';
}
function chatPane(){
 const person=data.employees.find(e=>e.id===chatEmployee)||data.employees[0]||{name:'Devy',role:'Boss'};
 const messages=(data.threads?.[chatEmployee]||[]);const waiting=messages.some(m=>m.status==='queued'||m.status==='running');
 const online=Boolean(data.bridge?.online);const connected=Boolean(data.bridge?.paired);
 return heading(person.name,person.focus||person.role,'<button class="btn" id="callButton">Call</button>')+
 '<div class="agent-tabs">'+data.employees.map(e=>'<button data-agent="'+e.id+'" class="'+(chatEmployee===e.id?'selected':'')+'">'+htmlEscape(e.name)+'</button>').join('')+'</div>'+
 '<section class="panel chat"><div class="chat-head"><span>'+(online?'Desktop connected':connected?'Desktop offline':'Connect Workforce to use ChatGPT')+'</span><button class="btn ghost" id="clearChat" '+(waiting?'disabled':'')+'>New chat</button></div>'+
 '<div class="chatstream" aria-live="polite">'+(messages.length?messages.map(m=>'<div class="bubble '+(m.by==='you'?'mine':'')+'"><small>'+(m.by==='you'?'You':htmlEscape(person.name))+' · '+new Date(m.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+(m.status==='queued'?' · queued':m.status==='running'?' · working':m.status==='failed'?' · failed':'')+'</small><article>'+((m.status==='queued'||m.status==='running')&&!m.text?'<span class="waiting">Working on your message…</span>':formatOfficeText(m.text))+'</article></div>').join(''):'<div class="chat-welcome"><strong>Message '+htmlEscape(person.name)+'</strong><p>Ask a question, assign work, or discuss a project.</p></div>')+'</div>'+
 '<form class="chatbar" id="messageform"><textarea id="message" aria-label="Message '+htmlEscape(person.name)+'" maxlength="4000" rows="1" placeholder="Message '+htmlEscape(person.name)+'…" required></textarea><button class="btn primary" id="send" '+(chatBusy?'disabled':'')+'>Send</button></form></section>';
}

function employeeWorkStatus(id){
 const jobs=(data.jobs||[]).filter(j=>j.employee===id);
 const running=jobs.find(j=>j.status==='running'),queued=jobs.find(j=>j.status==='queued');
 if(running)return {kind:'working',label:'Working',detail:running.kind==='meeting'?'In meeting':'Processing task'};
 if(queued)return {kind:'queued',label:'Queued',detail:queued.kind==='meeting'?'Joining meeting':'Waiting for desktop'};
 const assigned=data.tasks.filter(t=>t.employee===id&&t.status==='doing').length;
 return assigned?{kind:'assigned',label:'Assigned',detail:assigned+' in progress'}:{kind:'available',label:'Available',detail:'No active job'};
}
function officeDesk(e){
 const work=employeeWorkStatus(e.id);
 const meeting=(data.meetings||[]).find(m=>m.status==='running');
 const inMeeting=Boolean(meeting?.participants.includes(e.id));
 const active=work.kind==='working';
 return '<button class="work-desk '+work.kind+'" data-chat-person="'+e.id+'" title="Open conversation with '+htmlEscape(e.name)+'">'+
 '<div class="mini-scene"><span class="mini-monitor"><i></i></span><span class="mini-person '+(active?'at-work':'')+'"><i class="mini-head"></i><i class="mini-torso"></i><i class="mini-arm"></i></span><span class="mini-keyboard"></span></div>'+
 '<div class="desk-details"><strong>'+htmlEscape(e.name)+'</strong><span>'+htmlEscape(e.role)+'</span></div>'+
 '<div class="desk-foot"><i class="live-dot '+work.kind+'"></i><span>'+work.label+'</span>'+(inMeeting?'<span class="tiny-tag">Meeting</span>':'')+'</div></button>';
}
function officePane(){
 const meetings=(data.meetings||[]).slice().reverse();
 const active=meetings.find(m=>['running','review'].includes(m.status));
 const selected=meetings.find(m=>m.id===selectedMeetingId)||active||meetings[0];
 const workerOnline=Boolean(data.bridge?.online);
 const running=(data.jobs||[]).filter(j=>j.status==='running').length,queued=(data.jobs||[]).filter(j=>j.status==='queued').length;
 const team=data.employees||[];
 let detail='';
 if(!selected||(!active&&selectedMeetingId===null)){
 detail='<div class="meeting-intro"><h2>New meeting</h2><p>Set an agenda and select the people who should contribute. Each person takes a real turn through your desktop worker.</p></div>'+
 '<form id="meetingForm" class="meeting-form"><label>Title<input name="topic" required minlength="3" maxlength="150" placeholder="e.g. Review the next Office release"></label><label>Agenda<textarea name="agenda" required minlength="8" maxlength="3000" rows="4" placeholder="What should the team investigate, decide or deliver?"></textarea></label><span class="field-label">Participants</span><div class="meeting-select">'+team.map((e,i)=>'<label><input type="checkbox" name="participants" value="'+e.id+'" '+(i<4?'checked':'')+'><span>'+htmlEscape(e.name)+'</span></label>').join('')+'</div><button type="submit" class="btn primary meeting-primary">Start meeting</button><div class="meeting-footnote">'+(workerOnline?'Desktop online':'Your paired desktop is offline. The meeting will wait for it to connect.')+'</div></form>';
 }else{
 const speaker=selected.participants[selected.nextIndex];
 const latestJob=(data.jobs||[]).find(j=>j.meetingId===selected.id&&['queued','running'].includes(j.status));
 const noteItems=selected.minutes.map(item=>'<div class="minute-entry"><div class="minute-avatar">'+htmlEscape((team.find(e=>e.id===item.employee)?.name||'?')[0])+'</div><div><div class="minute-top"><strong>'+htmlEscape(team.find(e=>e.id===item.employee)?.name||item.employee)+'</strong><span>'+new Date(item.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+'</span></div><div class="meeting-prose">'+formatOfficeText(item.error?'Could not contribute: '+item.error:item.text)+'</div></div></div>').join('');
 detail='<div class="meeting-current"><div class="meeting-label">MEETING '+(selected.status==='running'?'IN PROGRESS':selected.status==='review'?'AWAITING REVIEW':selected.status.toUpperCase())+'</div><h2>'+htmlEscape(selected.topic)+'</h2><p>'+htmlEscape(selected.agenda)+'</p></div>'+
 '<div class="meeting-progress">'+selected.participants.map((id,i)=>'<span class="progress-person '+(i<selected.nextIndex?'done':i===selected.nextIndex&&selected.status==='running'?'now':'')+'" title="'+htmlEscape(team.find(e=>e.id===id)?.name||id)+'">'+htmlEscape((team.find(e=>e.id===id)?.name||id).slice(0,1))+'</span>').join('')+'<span class="meeting-progress-copy">'+(selected.status==='running'?(selected.nextIndex+' of '+selected.participants.length+' contributions'):(selected.minutes.length+' contributions') )+'</span></div>'+
 '<div class="meeting-minutes">'+(noteItems||'<div class="meeting-empty">Contributions appear here as employees finish real work.</div>')+
 (selected.status==='running'?'<div class="meeting-wait"><i class="live-dot '+(latestJob?.status==='running'?'working':'queued')+'"></i>'+(latestJob?.status==='running'?(htmlEscape(team.find(e=>e.id===speaker)?.name||'Employee')+' is responding…'):workerOnline?'Waiting for the next contribution':'Waiting for your desktop to come online')+'</div>':'')+'</div>'+
 (selected.notes||[]).map(n=>'<div class="meeting-owner-note"><strong>Your note</strong><span>'+htmlEscape(n.text)+'</span></div>').join('')+
 (['running','review'].includes(selected.status)?'<form id="meetingNoteForm" class="meeting-inline"><input type="text" name="text" aria-label="Meeting note" maxlength="1500" placeholder="Add a meeting note…" required><button class="btn">Add note</button></form>':'')+
 (selected.status==='review'?'<div class="meeting-decision"><h3>Turn decisions into work</h3><form id="meetingTaskForm" class="meeting-action"><input name="title" maxlength="160" minlength="3" required placeholder="Action item title"><select name="employee">'+team.map(e=>'<option value="'+e.id+'">'+htmlEscape(e.name)+'</option>').join('')+'</select><button type="submit" class="btn">Create task</button></form><form id="meetingCloseForm"><textarea name="decision" maxlength="2000" placeholder="Summary / decisions (optional)" rows="2"></textarea><button type="submit" class="btn primary meeting-primary">Close meeting</button></form></div>':'')+
 (selected.status==='running'?'<button id="meetingCancel" class="btn ghost meeting-cancel">Cancel meeting</button>':'')+
 (selected.status==='closed'?'<div class="meeting-closed"><strong>Meeting completed</strong><p>'+htmlEscape(selected.decision||'No final summary recorded.')+'</p><span>'+selected.taskIds.length+' approved action item(s)</span></div>':'')+
 (selected.status==='cancelled'?'<div class="meeting-closed">Meeting cancelled.</div>':'');
 }
 const meetingAvatar=(id)=>{const e=team.find(x=>x.id===id);return '<span class="table-member"><i class="table-head"></i><i class="table-body"></i><small>'+htmlEscape(e?.name||id)+'</small></span>'};
 const peopleAtTable=active?.participants||[];
 const table='<div class="meeting-table-scene"><div class="table-surface"><span class="table-mark">DEVYS</span></div>'+peopleAtTable.map((id,i)=>'<div class="table-seat seat-'+i+'">'+meetingAvatar(id)+'</div>').join('')+'<span class="table-caption">'+(active?'Meeting in session':'Meeting room · Available')+'</span></div>';
 return '<div class="office-head"><div><h1>Office</h1><p>Your team, their real work, and meeting decisions.</p></div><span class="office-connected"><i class="live-dot '+(workerOnline?'working':'queued')+'"></i>'+(workerOnline?'Desktop connected':'Desktop offline')+'</span></div>'+
 '<div class="office-stats"><span><strong>'+running+'</strong> working</span><span><strong>'+queued+'</strong> queued</span><span><strong>'+data.tasks.filter(t=>t.status==='review').length+'</strong> for review</span></div>'+
 '<div class="office-layout">'+LivingOffice.markup({agents:team,runs:(data.jobs||[]).map(j=>({...j,agentId:j.employee})),activeRuns:(data.jobs||[]).filter(j=>j.status==='running').map(j=>j.id),meetings:meetings.map(m=>({...m,speaker:(data.jobs||[]).find(j=>j.meetingId===m.id&&j.status==='running')?.employee})),approvals:[]})+
 '<section class="office-meetings"><div class="office-section-head"><strong>Meeting room</strong><small>'+meetings.length+' session'+(meetings.length===1?'':'s')+'</small></div><div class="meeting-body">'+detail+'</div>'+
 (meetings.length?'<div class="meeting-history"><strong>Previous sessions</strong>'+meetings.slice(0,5).map(m=>'<button data-meeting-id="'+m.id+'" class="history-meeting '+(selected?.id===m.id?'chosen':'')+'"><span>'+htmlEscape(m.topic)+'</span><small>'+htmlEscape(m.status)+'</small></button>').join('')+(active?'':'<button id="meetingNew" class="btn ghost">+ New meeting</button>')+'</div>':'')+'</section></div>';
}
async function meetingRefresh(){const d=await api('state');data=d;if(page==='office')render();else data=d}
async function startMeeting(e){e.preventDefault();const f=new FormData(e.currentTarget);const participants=f.getAll('participants');try{const r=await api('meetings','POST',{topic:f.get('topic'),agenda:f.get('agenda'),participants});selectedMeetingId=r.meeting.id;await meetingRefresh();toast(r.desktopOnline?'Meeting started':'Meeting queued. Open your desktop app to begin.')}catch(ex){toast(ex.message)}}
async function meetingAction(e,path,payload){e.preventDefault();const id=(data.meetings||[]).find(m=>m.id===selectedMeetingId)?.id||(data.meetings||[]).find(m=>['running','review'].includes(m.status))?.id;if(!id)return;try{await api('meetings/'+id+'/'+path,'POST',payload);await meetingRefresh();toast(path==='task'?'Action item created':path==='close'?'Meeting closed':'Saved')}catch(ex){toast(ex.message)}}
async function cancelMeeting(){const id=(data.meetings||[]).find(m=>m.status==='running')?.id;if(!id||!confirm('Cancel this meeting and all pending turns?'))return;try{await api('meetings/'+id+'/cancel','POST',{});selectedMeetingId=null;await meetingRefresh();toast('Meeting cancelled')}catch(ex){toast(ex.message)}}

