async function saveTask(e){e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{await api(modal.kind==='create'?'tasks':'tasks/'+modal.id,modal.kind==='create'?'POST':'PATCH',b);modal=null;await refresh();toast('Task saved')}catch(ex){toast(ex.message)}}
