async function logout(){try{await api('logout','POST',{})}catch{}session=null;cs='';endCall();render()}
function endCall(){callState='idle';callAwaiting=false;try{recognizer?.abort()}catch{}recognizer=null;window.speechSynthesis?.cancel()}
function say(text){if(!('speechSynthesis' in window))return;try{recognizer?.abort()}catch{}const utter=new SpeechSynthesisUtterance(String(text).replace(/[*_\`#]/g,'').slice(0,1700));utter.lang='en-US';utter.rate=1.02;utter.onstart=()=>{if($('#callstatus'))$('#callstatus').textContent='Boss speaking…'};utter.onend=()=>{if(callState==='active')listenTurn()};window.speechSynthesis.cancel();window.speechSynthesis.speak(utter)}
function listenTurn(){if(callState!=='active'||callAwaiting)return;const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){if($('#callstatus'))$('#callstatus').textContent='Voice recognition unavailable in this browser.';return}
 try{recognizer=new SR();recognizer.lang='en-US';recognizer.interimResults=true;recognizer.continuous=false;let committed=false;
 recognizer.onresult=async event=>{const pieces=Array.from(event.results);const phrase=pieces.map(r=>r[0]?.transcript||'').join(' ').trim();if($('#callstatus'))$('#callstatus').textContent=phrase||'Listening…';if(!pieces.some(r=>r.isFinal)||committed||!phrase)return;committed=true;try{recognizer.stop()}catch{}callAwaiting=true;
 try{const r=await api('chat','POST',{employee:'devy',message:phrase});if(r.reply){callAwaiting=false;callOutputId=(data.threads?.devy||[]).at(-1)?.id||'';say(r.reply)}else{if($('#callstatus'))$('#callstatus').textContent='Boss is thinking…'}}catch(e){callAwaiting=false;if($('#callstatus'))$('#callstatus').textContent=e.message}
 };
 recognizer.onerror=e=>{if($('#callstatus'))$('#callstatus').textContent='Microphone: '+e.error};recognizer.onend=()=>{if(callState==='active'&&!callAwaiting&&!committed)setTimeout(listenTurn,700)};recognizer.start();if($('#callstatus'))$('#callstatus').textContent='Listening…';
 }catch(e){if($('#callstatus'))$('#callstatus').textContent=e.message}}
