  s.jobs.push(job);s.jobs=s.jobs.slice(-350);task.status='doing';task.updated=now();audit(s,'job.queued',`Sent ${task.title} to ${employee?.name||'employee'}`);save(s);
  return json({job:{id:job.id,status:job.status}},202,headers);
