  if(m[2]==='notes'&&method==='POST'){let b;try{b=await limitBody(req)}catch{return err('Invalid request')};const note=safeText(b.text,1000);if(!note)return err('Write a note');task.notes??=[];task.notes.push({id:uuid(),text:note,at:now()});task.updated=now();audit(s,'task.note',`Added note to ${task.title}`);save(s);return json({ok:true},200,headers)}
  if(method==='PATCH'){let b;try{b=await limitBody(req)}catch{return err('Invalid request')};const title=safeText(b.title,160);if(title.length<3)return err('Task title must have at least 3 characters');if(!originalEmployees.some(x=>x.id===b.employee)||!isStatus(b.status)||!isPriority(b.priority))return err('Invalid assignee, status or priority');const old=task.status;Object.assign(task,{title,description:safeText(b.description,4000),employee:b.employee,status:b.status,priority:b.priority,due:safeText(b.due,10),updated:now()});audit(s,'task.updated',`Updated ${title}${old!==b.status?' to '+b.status:''}`);save(s);return json({task},200,headers)}
